document.addEventListener("DOMContentLoaded",function(){const dlg=document.getElementById("fico-formula-dialog");if(!dlg)return;const body=dlg.querySelector("tbody");const add=document.getElementById("fico-add-row");const remove=document.getElementById("fico-remove-row");if(add)add.addEventListener("click",function(){const n=body.rows.length;if(n>=40)return;const row=body.insertRow();const last=body.rows[n-1];for(let i=0;i<2;i++){const cell=row.insertCell();const input=document.createElement("input");input.type="number";input.name=(i===0?"fico_threshold[":"fico_points[")+n+"]";input.min="0";input.max=i===0?"850":String(document.querySelector("#fico-formula-dialog input[name^=fico_points]").max);input.step=i===0?"1":"any";input.required=true;input.style.width="110px";input.value=i===0?Math.max(0,Number(last.cells[0].querySelector("input").value)-5):0;cell.appendChild(input)}const colourCell=row.insertCell();const colourInput=last.querySelector("input[type=color]").cloneNode(true);colourInput.name="condition_color["+n+"]";colourCell.appendChild(colourInput);row.scrollIntoView({block:"nearest"})});if(remove)remove.addEventListener("click",function(){if(body.rows.length>1)body.deleteRow(-1)});const renumber=()=>Array.from(body.rows).forEach((r,i)=>Array.from(r.querySelectorAll("input")).forEach((x,j)=>x.name=(j===0?"fico_threshold[":j===1?"fico_points[":"condition_color[")+i+"]"));const decorate=()=>{Array.from(body.rows).forEach(r=>{if(false){const c=r.insertCell();c.style.whiteSpace="nowrap";for(const [label,delta] of [["↑",-1],["↓",1]]){const b=document.createElement("button");b.type="button";b.textContent=label;b.title=delta<0?"Move up":"Move down";b.className="fico-move";b.setAttribute("aria-label",b.title);b.addEventListener("click",()=>{const target=delta<0?r.previousElementSibling:r.nextElementSibling;if(!target)return;if(delta<0)body.insertBefore(r,target);else body.insertBefore(target,r);renumber()});c.appendChild(b)}}});renumber()};decorate();if(add)add.addEventListener("click",decorate);const sort=document.getElementById("fico-sort-rows");if(sort)sort.addEventListener("click",()=>{Array.from(body.rows).sort((a,b)=>Number(b.cells[0].querySelector("input").value)-Number(a.cells[0].querySelector("input").value)).forEach(r=>body.appendChild(r));renumber()});const form=body.closest("form");if(form)form.addEventListener("submit",renumber);});
